def showInLines():
    with open("STORY.TXT",'r') as F:
        S=F.read()
        for W in S:
            if W=="." or W=="?" or W=="!":
                print(W)
            elif W=="\n":
                print(end="")
            else:
                print(W,end="")
    F.close()

