def showInLines():
    F = open("STORY.TXT",'r')
    S=F.read()
    for W in S:
        if W.endswith(".") or W.endswith("?") or W.endswith("!"):
            print(W)
        elif W=="\n":
            print(end="")
        else:
            print(W,end="")
    F.close()

